import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as d}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const L=JSON.parse('{"title":"LLM 心智模型（桥接）","description":"LLM 是参数化条件概率模型、逐 token 预测下一个词——这一个心智模型决定 prompt 的真实作用、context 为何是硬约束、temperature 为何不是创造力旋钮；推导与实现归 Learn LLM。","frontmatter":{"title":"LLM 心智模型（桥接）","description":"LLM 是参数化条件概率模型、逐 token 预测下一个词——这一个心智模型决定 prompt 的真实作用、context 为何是硬约束、temperature 为何不是创造力旋钮；推导与实现归 Learn LLM。","domain":"tech","tags":["tech","model-lifecycle","bridge","mental-model"],"navOrder":11,"topicId":"llm-mental-model","layer":"1","status":"bridge","nodeType":"concept","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/chapters/04-probabilistic-lm"}],"prerequisites":["model-lifecycle-bridge"],"next":["architecture"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/01-model-lifecycle/llm-mental-model.md","filePath":"zh/tech/01-model-lifecycle/llm-mental-model.md","lastUpdated":1791118227000}'),n={name:"zh/tech/01-model-lifecycle/llm-mental-model.md"};function l(o,t,h,i,s,p){return a(),r("div",null,[...t[0]||(t[0]=[d('<blockquote><p><strong>在哪一组</strong>：组 01 · 模型生命周期（桥接组）｜ <strong>上一组出口</strong>：能判断知识归属、并为需求选出最低复杂度方案（00-map 组） ｜ <strong>本页出口</strong>：能用「参数化条件概率模型」解释 prompt、context 与 temperature 的真实作用，并对幻觉建立正确预期 <strong>前置</strong>：<a href="./index.html">模型生命周期（组导览）</a> ｜ <strong>下一步</strong>：<a href="./architecture.html">模型架构（桥接）</a></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：大语言模型（LLM）是一个<strong>参数化条件概率模型</strong>——用海量文本训练出一组权重，给定前文 token 序列，输出下一个 token 的概率分布，采样后循环生成。这个定义不是学术装饰：你对 prompt 策略、上下文预算、幻觉与模型选型的每一个工程判断，都是这个定义的推论。本页只建立这个心智模型并说明它影响哪些决策；概率语言模型的手写实现与损失函数推导归 <a href="https://llm.zenheart.site/chapters/04-probabilistic-lm" target="_blank" rel="noreferrer">Learn LLM 第 4 章</a>。</p><h3 id="三个直接推论" tabindex="-1">三个直接推论 <a class="header-anchor" href="#三个直接推论" aria-label="Permalink to &quot;三个直接推论&quot;">​</a></h3><ol><li><strong>Prompt 是调用能力，不是注入知识</strong>。模型的能力在训练时固化进权重；prompt 决定激活哪些能力、以什么格式输出。想让模型「知道」训练数据里没有的事实，唯一可靠通道是把事实放进上下文（<a href="./../03-context/">03-context 组</a>）或检索（<a href="./../04-grounding/rag.html">RAG</a>），而不是在指令里反复强调。</li><li><strong>Context window 是硬约束</strong>。模型只能条件于当前上下文内的 token；超出窗口的内容不存在「被记住」，会话历史必须由你显式携带并为此付费。上下文工程因此是一门取舍学科，不是「尽量塞满」。</li><li><strong>Temperature 是采样参数，不是创造力旋钮</strong>。它调整下一个 token 采样分布的平坦程度：低温偏向高概率 token（更稳定），高温更随机（更多样）。它改变输出的分布形状，不能让模型产出超出权重能力的正确答案——用它修不了能力问题。</li></ol><h3 id="三个常见误解勘误" tabindex="-1">三个常见误解勘误 <a class="header-anchor" href="#三个常见误解勘误" aria-label="Permalink to &quot;三个常见误解勘误&quot;">​</a></h3><table tabindex="0"><thead><tr><th>误解</th><th>更正</th></tr></thead><tbody><tr><td>LLM = ChatGPT</td><td>ChatGPT 是产品：LLM + 后训练 + 系统提示 + 工具与界面包装；同一模型在不同产品里行为不同</td></tr><tr><td>LLM = RAG</td><td>RAG 是应用层的检索模式，模型本身不检索；两者常组合但相互正交</td></tr><tr><td>LLM = Agent</td><td>Agent 是调用模型的编排循环（规划-行动-观察）；模型只是循环里的推理部件</td></tr></tbody></table><p>这三条的分界线详见<a href="./../00-map/site-boundaries.html">站点边界</a>；Agent 编排归 06-agent-systems 组。</p><h2 id="_2-何时跳转" tabindex="-1">2. 何时跳转 <a class="header-anchor" href="#_2-何时跳转" aria-label="Permalink to &quot;2. 何时跳转&quot;">​</a></h2><p>本页无可运行产物；替代动作是按下表把症状路由到正确的 owner：</p><table tabindex="0"><thead><tr><th>症状 / 问题</th><th>该读哪</th><th>为什么</th></tr></thead><tbody><tr><td>想理解「预测下一个词」的数学、loss 是什么</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/04-probabilistic-lm" target="_blank" rel="noreferrer">第 4 章</a></td><td>条件概率语言模型的 canonical 推导</td></tr><tr><td>token 是什么、为什么按 token 计费</td><td>Learn LLM <a href="https://llm.zenheart.site/chapters/05-bpe" target="_blank" rel="noreferrer">第 5 章</a></td><td>BPE 分词的从零实现</td></tr><tr><td>temperature / top-p 怎么调</td><td>本仓 <a href="./../03-context/prompt.html">提示词工程</a></td><td>应用层参数策略归本仓</td></tr><tr><td>模型不肯稳定输出 JSON</td><td>本仓 <a href="./../02-inference-interface/structured-output.html">结构化输出</a></td><td>是接口契约问题，不是模型理解问题</td></tr><tr><td>模型「不知道」训练后新出现的事实</td><td>本仓 <a href="./../04-grounding/rag.html">RAG</a></td><td>知识缺失走检索，不走 prompt</td></tr></tbody></table><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><p>一段定位：LLM 的训练目标是最大化训练语料上下一 token 的似然；能力是从数据分布与规模中涌现的统计规律，而不是被逐条写入的规则。工程师视角所需的全部原理到此为止——交叉熵、采样策略、从 Bigram 到 Transformer 的演进链，Learn LLM 第 4–5 章有从零手写的完整推导（retrievedAt 2026-09-01），本仓不复制第二份。</p><h2 id="_4-工程决策影响" tabindex="-1">4. 工程决策影响 <a class="header-anchor" href="#_4-工程决策影响" aria-label="Permalink to &quot;4. 工程决策影响&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工程决策</th><th>由心智模型推出的判断</th><th>错误预期会付出的代价</th></tr></thead><tbody><tr><td>模型选型</td><td>能力固化在权重里；同家族不同规格 = 能力-成本曲线上不同的点，按任务分级选型</td><td>用最大模型做全部任务，账单失控</td></tr><tr><td>Prompt 策略</td><td>指令用于调用与格式化已有能力；事实进上下文</td><td>把知识写进长指令：不稳定、不可更新、按 token 重复计费</td></tr><tr><td>上下文预算</td><td>上下文是唯一输入通道且计费；历史要裁剪与摘要</td><td>无脑拼接会话历史，成本与延迟随之恶化</td></tr><tr><td>幻觉预期</td><td>概率模型可能生成流畅但不为真的续写；这是机制的产物，只能管控、不能「提示掉」</td><td>指望一句「请不要编造」替代 grounding 与评估</td></tr><tr><td>输出稳定性</td><td>temperature 影响分布形状，不影响能力上限</td><td>调温修格式问题（正确解：结构化输出或改 prompt）</td></tr></tbody></table><p>维护规则（替代 runbook）：Learn LLM 第 4/5 章结构调整时重验本页 deep-link 并更新 <code>lastVerified</code>；本仓侧新增应用决策主题时只在上表加一行，不扩写原理。</p><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>四级阅读路线：</p><table tabindex="0"><thead><tr><th>级</th><th>读什么</th><th>为什么是这个顺序</th></tr></thead><tbody><tr><td>Beginner</td><td>本页 + <a href="./index.html">组导览</a></td><td>先建立两条链与一个心智模型</td></tr><tr><td>Builder</td><td>本仓 <a href="./../03-context/prompt.html">提示词工程</a> + <a href="./../02-inference-interface/structured-output.html">结构化输出</a></td><td>把心智模型落成接口契约</td></tr><tr><td>Operator</td><td><a href="./../04-grounding/rag.html">RAG</a> + <a href="./../08-production/evaluation.html">评估</a></td><td>用 grounding 与评估管控幻觉</td></tr><tr><td>Researcher</td><td>Learn LLM 第 4–5 章 + GPT-3 论文</td><td>下沉到概率模型与 in-context learning 的原始论述</td></tr></tbody></table><h3 id="资源表" tabindex="-1">资源表 <a class="header-anchor" href="#资源表" aria-label="Permalink to &quot;资源表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>层级</th><th>canonical URL</th><th>支持的断言</th><th>下一步</th></tr></thead><tbody><tr><td>Learn LLM 第 4 章 · 字符语言模型</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/04-probabilistic-lm" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/04-probabilistic-lm</a></td><td>条件概率与采样是 LLM 的核心机制</td><td>手写 Bigram → MLP</td></tr><tr><td>Learn LLM 第 5 章 · BPE</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/05-bpe" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/05-bpe</a></td><td>token 是计费与上下文的计量单位</td><td>理解 token 成本结构</td></tr><tr><td>Learn LLM 第 15 章 · Prompt 与记忆</td><td>E</td><td><a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/15-prompt-memory</a></td><td>应用侧 prompt 策略的系统论述</td><td>对照本仓 03-context 组</td></tr><tr><td>GPT-3 论文（Language Models are Few-Shot Learners）</td><td>L4</td><td><a href="https://arxiv.org/abs/2005.14165" target="_blank" rel="noreferrer">https://arxiv.org/abs/2005.14165</a></td><td>prompt 调用预训练能力的原始证据（in-context learning）</td><td>读 few-shot 各节</td></tr></tbody></table><p>（Learn LLM 章节经其章节目录核验、arXiv 链接为稳定 abs 地址，retrievedAt 均为 2026-09-01。）</p><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li>证伪入口：如果你发现某工程判断必须依赖采样数学或损失函数细节（如自实现约束解码），它属于 Learn LLM 或本仓 02-inference-interface 组，不是本页——请把断言下沉到正确 owner，不要在此扩写。</li><li>未决：「ChatGPT 产品构成」勘误中的系统提示与工具包装细节随厂商迭代漂移，未逐项核验；只作方向性勘误使用。</li></ul><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>概率语言模型的推导与实现：Learn LLM <a href="https://llm.zenheart.site/chapters/04-probabilistic-lm" target="_blank" rel="noreferrer">第 4 章</a>——本仓到此为止。</li><li>用这个心智模型造接口：本仓 <a href="./../02-inference-interface/">02-inference-interface 组</a>。</li><li>组内下一页：<a href="./architecture.html">模型架构（桥接）</a>。</li></ul>',26)])])}const u=e(n,[["render",l]]);export{L as __pageData,u as default};
